const slugify = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")

const preparation: Record<TopicKind, string> = {
  condition: "Prepara una cronología de síntomas, resultados anteriores y la lista de medicamentos y suplementos. Señala qué actividades se han visto afectadas.",
  procedure: "Solicita instrucciones de la técnica concreta: ayuno, medicamentos, acompañante y cuidados al volver a casa. No suspendas tratamientos por iniciativa propia.",
  test: "Confirma la preparación con el centro: no todas las pruebas requieren ayuno o cambios de medicamentos. Lleva la solicitud y los resultados previos relacionados.",
}

const followup: Record<TopicKind, string> = {
  condition: "Acuerda qué cambios registrar, cuándo revisar la respuesta y cómo contactar al equipo. La ausencia de síntomas no siempre permite suspender controles.",
  procedure: "Pide por escrito el cuidado de heridas o accesos si existen, las restricciones de actividad y la próxima revisión. Confirma quién comunicará resultados pendientes.",
  test: "Confirma quién interpretará el informe y cuándo lo recibirás. Un resultado aislado debe valorarse junto con tus antecedentes y otras pruebas.",
}

export function createExpandedGuides(specialties: CareGuide[]): CareGuide[] {
  return expandedTopicGroups.flatMap(group => {
    const parent = specialties.find(item => item.slug === group.specialty)
    if (!parent) throw new Error(`Especialidad no encontrada: ${group.specialty}`)
    return group.entries.map(([focus, overview, question, source]) => {
      const recommendations: Record<DisciplineId, string[]> = {
        enfermeria: [preparation[group.kind], "Solicita una explicación práctica de los cuidados que sí correspondan a tu caso y anota un teléfono de contacto."],
        medicina: [question, "Acuerda con el equipo el objetivo de la atención, las alternativas y el siguiente paso antes de terminar la consulta."],
        farmacia: ["Lleva una lista con nombres, dosis y horarios de tus medicamentos, incluidos suplementos y productos sin receta.", "Pregunta si tu plan necesita algún ajuste y quién debe indicarlo; no cambies dosis por una recomendación general."],
        nutricion: [group.kind === "condition" ? "Consulta si hay alguna necesidad nutricional relacionada con tu diagnóstico, pérdida de peso o dificultad para comer." : "Confirma si existe preparación alimentaria o ayuno y cómo reanudarás alimentos y líquidos después.", "Las restricciones de alimentos y líquidos deben individualizarse; solicita orientación si tienes otra enfermedad que modifica tu alimentación."],
        fisioterapia: [group.kind === "procedure" ? "Solicita límites concretos de carga y movimiento, y pregunta si necesitas rehabilitación para recuperar una función." : "Describe dificultades para caminar, mantener una postura o realizar tareas para valorar si necesitas apoyo funcional.", "Acuerda una actividad adecuada a tu situación; una prueba o un diagnóstico no implica por sí solo necesitar fisioterapia."],
        psicologia: ["Escribe tus dudas y comunica cómo la incertidumbre, el dolor o los cambios de rutina afectan tu bienestar.", "Si lo deseas, invita a una persona de confianza a la consulta y solicita apoyo cuando la preocupación interfiera con el descanso o tus actividades."],
      }
      return {
        slug: `${parent.slug}-${slugify(focus)}`, specialtySlug: parent.slug,
        category: parent.category, name: parent.name, description: parent.description,
        focus, overview, audience: `Personas que buscan orientación inicial sobre ${focus.toLocaleLowerCase("es")}, junto con su familia o red de apoyo. Las decisiones se adaptan a la edad y situación clínica.`,
        recommendations,
        urgent: "Ante dificultad respiratoria intensa, pérdida de conciencia, sangrado abundante, debilidad súbita o deterioro rápido, busca atención de emergencia. No esperes a la siguiente cita.",
        contact: "Contacta al equipo ante síntomas nuevos o crecientes, dificultades para seguir el plan o resultados que no llegan en el plazo acordado. Pide las señales de alarma específicas de tu situación.",
        takeaways: [question, "Tengo por escrito las indicaciones que se aplican a mi situación.", "Sé cuándo será mi revisión y cómo pedir ayuda si algo cambia."],
        education: {
          signs: `${overview} Registra cambios y su momento de inicio para comentarlos con el equipo.`,
          evaluation: `${question} La valoración integra antecedentes, exploración y pruebas seleccionadas según la pregunta clínica.`,
          preparation: preparation[group.kind], followup: followup[group.kind],
        },
        references: [{title: `Información de referencia: ${focus}`, organization: "Biblioteca Nacional de Medicina de EE. UU. · MedlinePlus en español", url: `https://medlineplus.gov/spanish/${source}`}],
      }
    })
  })
}
